<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CatalogOptionsService;
use EventMenu\Services\PublicOrderService;
use EventMenu\Services\WaiterCallService;

$pdo=Database::connection();
$token=trim((string)($_GET['t']??''));
$s=$pdo->prepare('SELECT rt.*,t.name tenant_name,t.id tenant_id,t.status tenant_status,t.primary_color,t.secondary_color,t.settings tenant_settings FROM restaurant_tables rt JOIN tenants t ON t.id=rt.tenant_id WHERE rt.qr_token=? LIMIT 1');
$s->execute([$token]);
$table=$s->fetch();
if(!$table||$table['tenant_status']!=='active'||$table['status']==='inactive'){http_response_code(404);exit('Mesa não encontrada ou indisponível.');}
$tenantId=(int)$table['tenant_id'];$unitId=$table['unit_id']?(int)$table['unit_id']:null;
try{$m=$pdo->prepare('SELECT enabled FROM tenant_modules WHERE tenant_id=? AND module_key="restaurant" LIMIT 1');$m->execute([$tenantId]);$enabled=$m->fetchColumn();if($enabled!==false&&!(bool)$enabled){http_response_code(404);exit('Atendimento de mesa indisponível.');}}catch(Throwable){}

$settings=json_decode((string)($table['tenant_settings']??'{}'),true);if(!is_array($settings))$settings=[];
$primary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($table['primary_color']??''))?(string)$table['primary_color']:'#6d4aff';
$secondary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($table['secondary_color']??''))?(string)$table['secondary_color']:'#8b5cf6';
$background=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($settings['menu_background_color']??''))?(string)$settings['menu_background_color']:'#f6f5fa';
$logo=trim((string)($settings['menu_logo_url']??''));$banner=trim((string)($settings['menu_banner_url']??''));
$headline=trim((string)($settings['menu_headline']??''))?:$table['tenant_name'];
$subtitle=trim((string)($settings['menu_subtitle']??''))?:'Peça pelo celular e envie direto para sua comanda';
$showImages=(bool)($settings['menu_show_images']??true);$showDescriptions=(bool)($settings['menu_show_descriptions']??true);$showPreparation=(bool)($settings['menu_show_preparation']??true);$showBadges=(bool)($settings['menu_show_badges']??true);$showFeatured=(bool)($settings['menu_show_featured']??true);$searchEnabled=(bool)($settings['menu_search_enabled']??true);

$cartKey='table:'.$token;if(!isset($_SESSION['public_carts'][$cartKey])||!is_array($_SESSION['public_carts'][$cartKey]))$_SESSION['public_carts'][$cartKey]=[];$cart=&$_SESSION['public_carts'][$cartKey];
$error=null;$notice=null;$self=app_url('/mesa.php?t='.urlencode($token));
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada. Atualize a página.';
    else try{
        $action=(string)($_POST['action']??'');
        if($action==='call'){
            $type=(string)($_POST['type']??'waiter');(new WaiterCallService())->createByTableToken($token,$type);
            $notice=match($type){'bill'=>'Conta solicitada. A equipe foi avisada.','help'=>'Pedido de ajuda enviado.','waiter'=>'Garçom chamado. A equipe foi avisada.',default=>'Solicitação enviada.'};
        }elseif($action==='add'){
            $id=(int)($_POST['product_id']??0);$qty=max(1,min(50,(int)($_POST['qty']??1)));$optionIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['option_ids']??[])),fn($v)=>$v>0)));sort($optionIds);
            $p=$pdo->prepare('SELECT id,unit_id,track_stock,stock_qty FROM products WHERE id=? AND tenant_id=? AND active=1');$p->execute([$id,$tenantId]);$prod=$p->fetch();
            if(!$prod||($unitId&&$prod['unit_id']!==null&&(int)$prod['unit_id']!==$unitId))throw new RuntimeException('Produto indisponível nesta mesa.');
            if((bool)$prod['track_stock']&&(int)$prod['stock_qty']<$qty)throw new RuntimeException('Quantidade indisponível em estoque.');
            (new CatalogOptionsService())->validateSelection($pdo,$tenantId,$id,$optionIds);$key=hash('sha256',$id.'|'.implode(',',$optionIds));
            if(isset($cart[$key]))$cart[$key]['qty']=min(50,(int)$cart[$key]['qty']+$qty);else$cart[$key]=['product_id'=>$id,'qty'=>$qty,'option_ids'=>$optionIds];
            header('Location: '.$self.'#produtos',true,303);exit;
        }elseif($action==='qty'){
            $key=(string)($_POST['line_key']??'');$qty=max(0,min(50,(int)($_POST['qty']??0)));if(isset($cart[$key])){if($qty===0)unset($cart[$key]);else$cart[$key]['qty']=$qty;}header('Location: '.$self.'#carrinho',true,303);exit;
        }elseif($action==='remove'){
            $key=(string)($_POST['line_key']??'');unset($cart[$key]);header('Location: '.$self.'#carrinho',true,303);exit;
        }elseif($action==='checkout'){
            if(!$cart)throw new RuntimeException('Adicione pelo menos um item.');
            $result=(new PublicOrderService())->createTable($token,array_values($cart),['name'=>(string)($_POST['name']??''),'phone'=>(string)($_POST['phone']??'')]);$cart=[];
            header('Location: '.app_url('/pedido.php?t='.urlencode($result['public_token'])),true,303);exit;
        }
    }catch(Throwable$e){$error=$e->getMessage();}
}

$where='tenant_id=? AND active=1'.($unitId?' AND (unit_id IS NULL OR unit_id=?)':'');$args=$unitId?[$tenantId,$unitId]:[$tenantId];
$c=$pdo->prepare('SELECT * FROM categories WHERE '.$where.' ORDER BY sort_order,name');$c->execute($args);$categories=$c->fetchAll();
$p=$pdo->prepare('SELECT * FROM products WHERE '.$where.' ORDER BY featured DESC,category_id,name');$p->execute($args);$products=$p->fetchAll();$byId=[];foreach($products as$prod)$byId[(int)$prod['id']]=$prod;
$groups=[];$options=[];$productIds=array_keys($byId);
if($productIds){$marks=implode(',',array_fill(0,count($productIds),'?'));$g=$pdo->prepare('SELECT * FROM product_option_groups WHERE tenant_id=? AND product_id IN ('.$marks.') AND active=1 ORDER BY product_id,sort_order,id');$g->execute([$tenantId,...$productIds]);foreach($g->fetchAll()as$r)$groups[(int)$r['product_id']][]=$r;$gids=[];foreach($groups as$rs)foreach($rs as$r)$gids[]=(int)$r['id'];if($gids){$marks=implode(',',array_fill(0,count($gids),'?'));$o=$pdo->prepare('SELECT * FROM product_options WHERE group_id IN ('.$marks.') AND active=1 ORDER BY group_id,sort_order,id');$o->execute($gids);foreach($o->fetchAll()as$r)$options[(int)$r['group_id']][]=$r;}}
$catalog=new CatalogOptionsService();$cartLines=[];$cartTotal=0;$cartCount=0;
foreach($cart as$key=>$row){$id=(int)$row['product_id'];if(!isset($byId[$id]))continue;try{$sel=$catalog->validateSelection($pdo,$tenantId,$id,(array)$row['option_ids']);}catch(Throwable){continue;}$pr=$byId[$id];$base=$pr['promo_price_cents']!==null?(int)$pr['promo_price_cents']:(int)$pr['price_cents'];$unitPrice=max(0,$base+(int)$sel['delta_cents']);$qty=(int)$row['qty'];$line=$unitPrice*$qty;$cartTotal+=$line;$cartCount+=$qty;$cartLines[]=['key'=>$key,'product'=>$pr,'qty'=>$qty,'options'=>$sel['options'],'unit_price'=>$unitPrice,'total'=>$line];}
$tab=$pdo->prepare('SELECT tb.id,tb.label,(SELECT COALESCE(SUM(o.total_cents),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") total,(SELECT COALESCE(SUM(CASE WHEN o.payment_status<>"paid" THEN o.total_cents ELSE 0 END),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") unpaid FROM tabs tb WHERE tb.tenant_id=? AND tb.table_id=? AND tb.status="open" LIMIT 1');$tab->execute([$tenantId,$table['id']]);$openTab=$tab->fetch();
function mesa_money(int$c):string{return'R$ '.number_format($c/100,2,',','.');}
$featured=array_values(array_filter($products,fn($p)=>!empty($p['featured'])));
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($primary) ?>"><title><?= Security::e($table['tenant_name']) ?> · <?= Security::e($table['name']) ?></title><link rel="manifest" href="<?= Security::e(app_url('/manifest.webmanifest')) ?>"><link rel="stylesheet" href="<?= Security::e(app_url('/assets/app.css')) ?>?v=92mesa-menu"><style>
