p:12px;flex-wrap:wrap;background:#ffffff1f;border:1px solid #ffffff42;border-radius:13px;padding:10px 12px;font-size:11px;font-weight:800;margin-top:12px}.category-wrap{background:#fff;border-bottom:1px solid #ecebf2;position:sticky;top:68px;z-index:28}.category-strip{max-width:1180px;margin:auto;padding:13px 18px;display:flex;gap:8px;overflow:auto;scrollbar-width:none}.category-strip a{white-space:nowrap;padding:9px 14px;border-radius:999px;border:1px solid #e5e3ed;color:#3e3e4b;font-size:11px;font-weight:850}.category-strip a:hover{background:var(--menu-primary);color:#fff;border-color:var(--menu-primary)}.menu-content{max-width:1180px;margin:auto;padding:22px 18px 110px}.menu-search{max-width:520px;margin-bottom:22px}.menu-search input{background:#fff;border:1px solid #e1dfe9;border-radius:14px;padding:13px 16px}.menu-section{margin-bottom:32px}.menu-section h2{font-size:24px;margin:0 0 14px}.product-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.menu-product{background:#fff;border:1px solid #e8e6ef;border-radius:17px;overflow:hidden;box-shadow:0 5px 18px rgba(38,30,60,.045);display:flex;flex-direction:column}.menu-product.hidden-search{display:none}.product-image{width:100%;aspect-ratio:16/10;object-fit:cover;background:#eee}.product-body{padding:14px;display:flex;flex-direction:column;gap:7px;flex:1}.product-body h3{font-size:16px;margin:0}.product-desc{color:#777788;font-size:11px;line-height:1.45;min-height:31px}.product-meta{display:flex;gap:6px;flex-wrap:wrap}.pill{font-size:9px;font-weight:900;border-radius:999px;background:#eeeaff;color:#5c42d7;padding:5px 8px}.price{font-size:17px;font-weight:900;color:var(--menu-primary)}.old-price{text-decoration:line-through;color:#9a9aa8;font-size:10px}.option-box{background:#f8f7fb;border-radius:11px;padding:8px}.option-box summary{cursor:pointer;font-size:10px;color:#5f45dd;font-weight:850}.option-group{margin-top:8px}.option-row{display:flex;justify-content:space-between;gap:8px;padding-top:6px;font-size:10px}.option-row input{width:auto;min-height:0}.add-row{display:flex;gap:7px;margin-top:auto}.add-row input{width:62px}.add-row button{flex:1;background:var(--menu-primary);color:#fff;border:0;border-radius:11px;font-weight:900}.cart-overlay{position:fixed;inset:0;background:#17122288;z-index:70;opacity:0;pointer-events:none;transition:.2s}.cart-drawer{position:fixed;right:0;top:0;bottom:0;width:min(440px,100%);background:#fff;z-index:80;transform:translateX(105%);transition:.25s;box-shadow:-25px 0 70px #15102035;display:flex;flex-direction:column}.cart-open .cart-overlay{opacity:1;pointer-events:auto}.cart-open .cart-drawer{transform:translateX(0)}.cart-head{height:70px;border-bottom:1px solid #ecebf2;display:flex;align-items:center;justify-content:space-between;padding:0 20px}.cart-head h2{margin:0}.cart-close{width:39px;height:39px;border:0;border-radius:11px;background:#f1eff5;font-size:22px}.cart-body{padding:14px 20px;overflow:auto;flex:1}.cart-line{padding:12px 0;border-bottom:1px solid #efedf3}.cart-line-top{display:flex;justify-content:space-between;gap:9px}.cart-line-options{font-size:10px;color:#81818e}.cart-line-actions{display:flex;gap:6px;margin-top:7px}.cart-line-actions form{display:flex;gap:5px}.cart-line-actions input{width:58px}.cart-summary{border-top:1px solid #eae8f0;padding:16px 20px 20px}.cart-total{display:flex;justify-content:space-between;font-size:20px;font-weight:900;margin-bottom:12px}.send-form{display:grid;grid-template-columns:1fr 1fr;gap:8px}.send-form label{font-size:10px;color:#666679}.send-form button{grid-column:1/-1;background:var(--menu-primary);color:#fff;border:0;border-radius:13px;min-height:48px;font-weight:900}.table-fab{display:none;position:fixed;bottom:13px;left:13px;right:13px;z-index:40;background:var(--menu-primary);color:#fff;border:0;border-radius:15px;min-height:54px;font-weight:900;box-shadow:0 15px 35px #2e225333}.notice-wrap{max-width:1180px;margin:12px auto 0;padding:0 18px}.empty{text-align:center;padding:48px 20px;background:#fff;border:1px solid #e8e6ed;border-radius:17px;color:#888}@media(max-width:850px){.product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.table-actions button:not(.cart-open-btn){padding:8px;font-size:0}.table-actions button:not(.cart-open-btn)::first-letter{font-size:13px}.table-hero{min-height:260px}.table-hero-inner{padding:40px 18px}.table-fab{display:block}}@media(max-width:560px){.product-grid{grid-template-columns:1fr 1fr;gap:9px}.menu-content{padding-left:10px;padding-right:10px}.product-body{padding:10px}.product-body h3{font-size:14px}.product-desc{font-size:10px}.table-brand small{display:none}.table-actions{gap:4px}.table-actions button{padding:8px}.table-hero h1{font-size:36px}.send-form{grid-template-columns:1fr}.send-form button{grid-column:1}.category-wrap{top:68px}}
</style></head><body class="table-menu"><header class="table-top"><div class="table-top-inner"><div class="table-brand"><?php if($logo):?><img src="<?= Security::e($logo) ?>" alt=""><?php endif;?><div><strong><?= Security::e($table['tenant_name']) ?></strong><small><?= Security::e($table['name']) ?> · Cardápio da mesa</small></div></div><div class="table-actions"><?php foreach(['waiter'=>'👋 Chamar garçom','bill'=>'🧾 Pedir conta','help'=>'❓ Ajuda']as$type=>$label):?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="call"><input type="hidden" name="type" value="<?= $type ?>"><button title="<?= Security::e($label) ?>"><?= Security::e($label) ?></button></form><?php endforeach;?><button class="cart-open-btn" type="button" data-open-cart>Pedido (<?= $cartCount ?>)</button></div></div></header>
<section class="table-hero<?= $banner?' has-banner':'' ?>"<?= $banner?' style="background-image:url(\''.Security::e($banner).'\')"':'' ?>><div class="table-hero-inner"><?php if($logo):?><img class="table-logo" src="<?= Security::e($logo) ?>" alt="Logo"><?php endif;?><div class="table-kicker">Cardápio Digital · <?= Security::e($table['name']) ?></div><h1><?= Security::e($headline) ?></h1><p><?= Security::e($subtitle) ?></p><?php if($openTab):?><div class="tab-summary"><span>Comanda #<?= (int)$openTab['id'] ?></span><span>Total <?= mesa_money((int)$openTab['total']) ?></span><span>Em aberto <?= mesa_money((int)$openTab['unpaid']) ?></span></div><?php endif;?></div></section>
<?php if($categories):?><div class="category-wrap"><nav class="category-strip"><?php if($showFeatured&&$featured):?><a href="#destaques">Destaques</a><?php endif;?><?php foreach($categories as$cat):?><a href="#cat-<?= (int)$cat['id'] ?>"><?= Security::e($cat['name']) ?></a><?php endforeach;?></nav></div><?php endif;?>
<?php if($notice||$error):?><div class="notice-wrap"><?php if($notice):?><div class="alert ok"><?= Security::e($notice) ?></div><?php endif;?><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?></div><?php endif;?>
<main class="menu-content" id="produtos"><?php if($searchEnabled):?><div class="menu-search"><input id="tableSearch" type="search" placeholder="Buscar no cardápio..."></div><?php endif;?><?php if($showFeatured&&$featured):?><section class="menu-section" id="destaques"><h2>Destaques</h2><div class="product-grid"><?php foreach($featured as$prod):?><?php $product=$prod;include __DIR__.'/partials/mesa_product_legacy.php';?><?php endforeach;?></div></section><?php endif;?><?php foreach($categories as$cat):$cp=array_values(array_filter($products,fn($p)=>(int)$p['category_id']===(int)$cat['id']));if(!$cp)continue;?><section class="menu-section" id="cat-<?= (int)$cat['id'] ?>"><h2><?= Security::e($cat['name']) ?></h2><div class="product-grid"><?php foreach($cp as$prod):?><?php $product=$prod;include __DIR__.'/partials/mesa_product_legacy.php';?><?php endforeach;?></div></section><?php endforeach;?><?php if(!$products):?><div class="empty"><h2>Cardápio em preparação</h2><p>Nenhum produto está disponível neste momento.</p></div><?php endif;?></main>
<div class="cart-overlay" data-close-cart></div><aside class="cart-drawer" id="carrinho"><div class="cart-head"><h2>Pedido da mesa</h2><button class="cart-close" type="button" data-close-cart>×</button></div><div class="cart-body"><?php if(!$cartLines):?><div class="empty"><strong>Seu pedido está vazio.</strong><p>Escolha os itens do cardápio.</p></div><?php else:?><?php foreach($cartLines as$line):?><div class="cart-line"><div class="cart-line-top"><strong><?= Security::e($line['product']['name']) ?></strong><strong><?= mesa_money($line['total']) ?></strong></div><?php if($line['options']):?><div class="cart-line-options"><?= Security::e(implode(' · ',array_column($line['options'],'name'))) ?></div><?php endif;?><div class="cart-line-actions"><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="qty"><input type="hidden" name="line_key" value="<?= Security::e($line['key']) ?>"><input type="number" name="qty" min="0" max="50" value="<?= (int)$line['qty'] ?>"><button class="secondary">Atualizar</button></form><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="line_key" value="<?= Security::e($line['key']) ?>"><button class="danger">Remover</button></form></div></div><?php endforeach;?><?php endif;?></div><?php if($cartLines):?><div class="cart-summary"><div class="cart-total"><span>Total</span><span><?= mesa_money($cartTotal) ?></span></div><form method="post" class="send-form"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="checkout"><label>Seu nome <small>(opcional)</small><input name="name" autocomplete="name"></label><label>Telefone <small>(opcional)</small><input name="phone" autocomplete="tel"></label><button>Enviar para a comanda</button></form><p class="muted" style="font-size:10px">O pedido será enviado para a operação desta mesa. Pagamento online ou no caixa depende das configurações do estabelecimento.</p></div><?php endif;?></aside><?php if($cartCount):?><button class="table-fab" type="button" data-open-cart>Ver pedido · <?= mesa_money($cartTotal) ?></button><?php endif;?>
<script>function syncOpts(form,gid){form.querySelectorAll('[data-option-group="'+gid+'"]').forEach(i=>i.remove());form.querySelectorAll('[name^="group_'+gid+'"]:checked').forEach(v=>{const i=document.createElement('input');i.type='hidden';i.name='option_ids[]';i.value=v.value;i.dataset.optionGroup=gid;form.appendChild(i);});}(()=>{const body=document.body;document.querySelectorAll('[data-open-cart]').forEach(b=>b.addEventListener('click',()=>body.classList.add('cart-open')));document.querySelectorAll('[data-close-cart]').forEach(b=>b.addEventListener('click',()=>body.classList.remove('cart-open')));const search=document.getElementById('tableSearch');if(search)search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();document.querySelectorAll('.menu-product').forEach(card=>card.classList.toggle('hidden-search',q!==''&&!card.dataset.search.includes(q)));});if(location.hash==='#carrinho')body.classList.add('cart-open');})();if('serviceWorker'in navigator)navigator.serviceWorker.register('<?= Security::e(app_url('/sw.js')) ?>').catch(()=>{});</script></body></html>
